function jsonFor(url, query, dev) {
  if (url.indexOf('state') > 0) return getState(dev);
  if (url.indexOf('info') > 0) return getInfo(dev);
  if (url.indexOf('si') > 0) return stateInfo(dev);
  if (url.indexOf('nodes') > 0) return { nodes: [] };
  if (url.indexOf('eff') > 0) return dev.effects;
  if (url.indexOf('palx') > 0) return dev.palx(parseInt(query.get('page') || '0', 10) || 0);
  if (url.indexOf('fxda') > 0) return dev.fxdata;
  if (url.indexOf('net') > 0) return { networks: [] };
  if (url.indexOf('cfg') > 0) return cfgJson(dev);
  if (url.indexOf('pins') > 0) return pinsJson();
  if (url.indexOf('live') > 0) return liveJson(dev);
  if (url.indexOf('pal') > 0) return dev.palettes;
  if (url.length > 6) return undefined;   // 501
  return Object.assign(stateInfo(dev), { effects: dev.effects, palettes: dev.palettes });
}
function serveJson(req, res, url, query, dev) {
  const o = jsonFor(url, query, dev);
  if (o === undefined) jsonError(req, res, 501, ERR_NOT_IMPL);
  else sendJson(req, res, 200, o);
}

// ---------------------------------------------------------------- settings (serveSettings / serveSettingsJS / xml.cpp)
function subPageOf(url) {
  if (url.indexOf('sett') >= 0) {
    if (url.indexOf('.js') > 0) return SUB.JS;
    if (url.indexOf('.css') > 0) return SUB.CSS;
    if (url.indexOf('wifi') > 0) return SUB.WIFI;
    if (url.indexOf('leds') > 0) return SUB.LEDS;
    if (url.indexOf('ui') > 0) return SUB.UI;
    if (url.indexOf('sync') > 0) return SUB.SYNC;
    if (url.indexOf('time') > 0) return SUB.TIME;
    if (url.indexOf('sec') > 0) return SUB.SEC;
    if (url.indexOf('um') > 0) return SUB.UM;
    if (url.indexOf('2D') > 0) return SUB.D2;
    if (url.indexOf('pins') > 0) return SUB.PINS;
    if (url.indexOf('lock') > 0) return SUB.LOCK;
    return SUB.MENU;
  }
  if (url.indexOf('/update') >= 0) return SUB.UPDATE;
  return SUB.WELCOME;
}
const SUB_PAGE = { [SUB.WIFI]: 'PAGE_settings_wifi', [SUB.LEDS]: 'PAGE_settings_leds', [SUB.UI]: 'PAGE_settings_ui',
  [SUB.SYNC]: 'PAGE_settings_sync', [SUB.TIME]: 'PAGE_settings_time', [SUB.SEC]: 'PAGE_settings_sec', [SUB.UM]: 'PAGE_settings_um',
  [SUB.UPDATE]: 'PAGE_update', [SUB.D2]: 'PAGE_settings_2D', [SUB.PINS]: 'PAGE_settings_pininfo', [SUB.CSS]: 'PAGE_settingsCss',
  [SUB.WELCOME]: 'PAGE_welcome', [SUB.MENU]: 'PAGE_settings' };
const SUB_NAME = { [SUB.WIFI]: 'WiFi', [SUB.LEDS]: 'LED', [SUB.UI]: 'UI', [SUB.SYNC]: 'Sync', [SUB.TIME]: 'Time',
  [SUB.SEC]: 'Security', [SUB.UM]: 'Usermods', [SUB.D2]: '2D' };

function serveSettings(req, res, url, query, dev, post) {
  const sub = subPageOf(url);
  if (post) {   // handleSettingsSet() is not emulated: say so, then go back to the menu like the device does
    const s = SUB_NAME[sub] || 'Settings';
    serveMessage(req, res, 200, `${s} settings not stored`, 'This is a virtual device. Redirecting...', 3);
    return;
  }
  if (sub === SUB.LOCK) { serveMessage(req, res, 200, 'No PIN set', 'Redirecting...', 1); return; }
  if (sub === SUB.JS) { serveSettingsJS(req, res, url, query, dev); return; }
  serveStatic(req, res, SUB_PAGE[sub] || 'PAGE_settings');
}

